"""One-transport private listening battle, with explicit review eligibility."""
TEMPLATE = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Skelly Sound Battles</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0c110f;color:#edf5ef;font:17px/1.5 system-ui}main{max-width:760px;margin:auto;padding:24px 16px}h1{font-size:30px}h2{margin:0;font-size:23px}p{color:#bccbc2}section{padding:20px;background:#18231d;border:1px solid #3e5946;border-radius:16px;margin:18px 0}button,select,textarea{font:inherit;background:#253e2d;color:inherit;border:1px solid #638369;border-radius:9px;padding:13px;min-height:48px}button{cursor:pointer}button:disabled{opacity:.4;cursor:default}button[aria-pressed=true]{outline:3px solid #b9e994;background:#385e36}.row{display:flex;gap:12px;margin:12px 0}.row>*{flex:1;min-width:0}select,textarea,audio{width:100%}textarea{min-height:80px}#original,#tie,#next,#export{width:100%}#next{background:#c1e4a2;color:#122211;font-weight:bold}.small{font-size:14px}#verification{color:#f1d18d}#active{font-weight:bold;color:#c2efa4}#reveal{overflow-wrap:anywhere}button:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid white}@media(max-width:480px){main{padding:12px}section{padding:15px}.row{gap:8px}button{padding:12px 5px}h1{font-size:26px}}
</style><main><h1>Skelly Sound Battles</h1><p id="progress"></p><select id="round" aria-label="Vocal preset"></select><section><h2 id="title"></h2><p id="verification" class="small"></p><p id="note" class="small"></p><button id="original">ORIGINAL REFERENCE</button><p class="small">Recreations</p><div class="row"><button id="a">A</button><button id="b">B</button><button id="c">C</button></div><p id="active" aria-live="polite">Choose a version</p><audio id="audio" controls preload="none"></audio></section><section><h2 id="decision">Keep the best two</h2><select id="rating" aria-label="Similarity rating"><option value="">Similarity to original</option><option value="1">1 - Far away</option><option value="2">2 - Some similarity</option><option value="3">3 - Getting close</option><option value="4">4 - Very close</option><option value="5">5 - Excellent match</option></select><p class="small" id="winnerlabel">Winner</p><div class="row"><button id="voteA">A wins</button><button id="voteB">B wins</button><button id="voteC">C wins</button></div><p class="small" id="droplabel">Eliminate</p><div class="row"><button id="dropA">Drop A</button><button id="dropB">Drop B</button><button id="dropC">Drop C</button></div><button id="tie">Too close / keep all three</button><p><textarea id="notes" aria-label="Feedback" placeholder="What should improve?"></textarea></p><button id="next">Save & next</button><p id="status" role="status"></p><p id="reveal" class="small"></p></section><button id="export">Download my picks</button><p class="small">Experimental audio. Protected owner choices remain unchanged until you approve a replacement.</p></main><script>
const LAB=/*DATA*/;const $=id=>document.getElementById(id),audio=$('audio'),key='skelly-battles-'+LAB.session_id;let votes={};try{votes=JSON.parse(localStorage.getItem(key)||'{}')}catch(_){}let n=0,active=null,epoch=0;
const group=()=>LAB.groups[n],state=()=>votes[group().id]||(votes[group().id]={winner:'',eliminate:'',notes:'',submitted:false});
function save(){try{localStorage.setItem(key,JSON.stringify(votes))}catch(_){}$('progress').textContent=LAB.groups.filter(g=>votes[g.id]?.submitted).length+' / '+LAB.groups.filter(g=>g.reviewable!==false).length+' available reviews completed'}
function stop(){epoch++;audio.pause();try{audio.currentTime=0}catch(_){}audio.removeAttribute('src');audio.load();active=null;for(const id of ['original','a','b','c'])$(id).setAttribute('aria-pressed','false');$('active').textContent='Choose a version'}
async function play(which){if(which!=='original'&&!group().candidates.some(c=>c.letter===which))return;if(active===which){if(audio.paused)await audio.play().catch(()=>{});else audio.pause();return}stop();const token=epoch;active=which;audio.src=which==='original'?group().reference:group().candidates[which.charCodeAt(0)-65].audio;audio.load();audio.currentTime=0;$(which==='original'?'original':which.toLowerCase()).setAttribute('aria-pressed','true');$('active').textContent=which==='original'?'ORIGINAL REFERENCE':'Recreation '+which;try{await audio.play()}catch(_){if(token===epoch)$('status').textContent='Press play to start this version.'}}
function mark(){for(const [id,v] of [['voteA','A'],['voteB','B'],['voteC','C'],['dropA','drop_A'],['dropB','drop_B'],['dropC','drop_C'],['tie','tie']]){$(id).setAttribute('aria-pressed',String(v.startsWith('drop_')?state().eliminate===v.slice(5):state().winner===v));$(id).disabled=group().reviewable===false||!group().candidates.some(c=>c.letter===v.slice(-1));if(id==='tie')$(id).disabled=group().reviewable===false;$(id).hidden=group().candidates.length<2}for(const l of 'ABC')$(l.toLowerCase()).disabled=!group().candidates.some(c=>c.letter===l);$('winnerlabel').hidden=group().candidates.length<2;$('droplabel').hidden=group().candidates.length<2;$('rating').hidden=group().candidates.length!==1;$('rating').disabled=group().reviewable===false;$('rating').value=state().rating||'';$('decision').textContent=!group().candidates.length?'Reference only':group().candidates.length===1?'Rate the new recreation':'Keep the best two';$('reveal').textContent=state().submitted?group().candidates.map(c=>c.letter+': '+c.identity).join(' | '):''}
function show(i){stop();n=i;$('round').value=String(i);$('title').textContent=group().title;$('verification').textContent=group().verification||'Experimental same-take comparison';$('note').textContent=group().note;$('notes').value=state().notes;$('status').textContent='';mark();save()}
LAB.groups.forEach((g,i)=>{const o=document.createElement('option');o.value=i;o.textContent=g.title;$('round').append(o)});$('round').onchange=()=>show(Number($('round').value));$('original').onclick=()=>play('original');$('a').onclick=()=>play('A');$('b').onclick=()=>play('B');$('c').onclick=()=>play('C');
for(const [id,v] of [['voteA','A'],['voteB','B'],['voteC','C'],['dropA','drop_A'],['dropB','drop_B'],['dropC','drop_C'],['tie','tie']])$(id).onclick=()=>{if(group().reviewable===false)return;state().submitted=false;if(v==='tie'){state().winner='tie';state().eliminate=''}else if(v.startsWith('drop_')){state().eliminate=v.slice(5);if(state().winner===state().eliminate||state().winner==='tie')state().winner=''}else{state().winner=v;if(state().eliminate===v)state().eliminate=''}mark();save()};
$('rating').onchange=()=>{state().rating=Number($('rating').value)||null;state().submitted=false;save();mark()};$('notes').oninput=()=>{state().notes=$('notes').value;save()};$('next').onclick=()=>{if(group().reviewable!==false){if(group().candidates.length===1?!state().rating:(!state().winner||(state().winner!=='tie'&&!state().eliminate))){$('status').textContent='Choose winner and weakest, or keep all three.';return}state().submitted=true}save();mark();stop();if(n<LAB.groups.length-1)show(n+1);else $('status').textContent='Saved. Download your picks below.'};
function feedback(){return {schema:'skelly.sound-battle-feedback.v2',session_id:LAB.session_id,previous_sessions:LAB.previous_sessions||[],results:LAB.groups.map(g=>{const v=votes[g.id]||{},eliminate=v.winner==='tie'?'':v.eliminate||'';return {group_id:g.id,preset:g.title,reviewable:g.reviewable!==false,verification:g.verification,submitted:!!v.submitted,rating:g.candidates.length===1?v.rating||null:null,winner:g.reviewable===false?'':v.winner||'',eliminate:g.reviewable===false?'':eliminate,survivors:g.candidates.filter(c=>g.reviewable===false||c.letter!==eliminate).map(c=>c.identity),notes:v.notes||'',reference_sha256:g.reference_sha256,candidate_versions:g.candidates.map(c=>({letter:c.letter,identity:c.identity,sha256:c.sha256,status:c.status}))}})}}
$('export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(feedback(),null,2)],{type:'application/json'}));a.download='SKELLY_BATTLE_PICKS.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000)};show(0);
</script></html>'''
